<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sharky — Hache Natación</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:1100px;margin:auto;padding:74px 14px 40px}.top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.top a{color:#123b5d;font-weight:800;text-decoration:none}.sub{color:#64748b;margin:5px 0 18px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.card,.panel{background:#fff;border-radius:16px;padding:15px;box-shadow:0 2px 10px rgba(15,23,42,.04)}.card strong{display:block;font-size:25px}.card span{color:#64748b;font-size:13px}.panel{margin-top:12px}.panel h2{margin:0 0 12px;font-size:19px}.msg{min-height:22px;font-weight:800;color:#b42318}.takeover{display:grid;grid-template-columns:120px 150px 1fr 165px;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #edf1f5}.takeover:last-child{border-bottom:0}.pill{display:inline-block;padding:5px 8px;border-radius:999px;background:#fff3cd;color:#7a4c00;font-size:12px;font-weight:800}.pill.collecting{background:#e8f1fb;color:#123b5d}.pill.candidate{background:#e8f7ee;color:#176b3a}.pill.review{background:#fff0ef;color:#a1261c}.summary{color:#475569;font-size:13px;line-height:1.35}.btn{border:0;border-radius:9px;padding:9px 11px;font-weight:800;cursor:pointer}.primary{background:#123b5d;color:#fff}.config-row{display:grid;grid-template-columns:260px 1fr 110px;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid #edf1f5}.config-row small{display:block;color:#64748b;margin-top:3px}.config-row input:not([type=checkbox]){width:100%;padding:9px 10px;border:1px solid #cbd5e1;border-radius:9px}.toggle{display:flex;align-items:center;gap:10px;font-weight:800}.toggle input{width:22px;height:22px;accent-color:#123b5d}.toggle span{color:#475569;font-size:13px}.metrics{width:100%;border-collapse:collapse}.metrics th,.metrics td{text-align:left;padding:8px;border-bottom:1px solid #edf1f5;font-size:13px}.brain-head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.brain-note{margin:8px 0 12px;color:#475569;font-size:13px;line-height:1.45}.brain-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.brain-card{border:1px solid #e7edf4;border-radius:12px;padding:12px}.brain-card strong{display:block;font-size:22px}.brain-card span{color:#64748b;font-size:12px}.brain-live{margin-top:14px;padding-top:14px;border-top:1px solid #e7edf4}.brain-live h3{margin:0 0 8px;font-size:16px}.brain-gate{margin-top:10px;padding:10px 12px;border-radius:10px;background:#f8fafc;color:#475569;font-size:13px;line-height:1.45}.danger-text{color:#a1261c;font-weight:800}.empty{color:#64748b;padding:8px 0}@media(max-width:850px){.grid,.brain-grid{grid-template-columns:repeat(2,1fr)}.takeover{grid-template-columns:1fr 1fr}.takeover .summary{grid-column:1/-1}.config-row{grid-template-columns:1fr 110px}.config-row .label{grid-column:1/-1}}@media(max-width:520px){.grid,.brain-grid{grid-template-columns:1fr 1fr}.takeover{grid-template-columns:1fr}.config-row{grid-template-columns:1fr}.config-row .label{grid-column:auto}}
</style>
</head>
<body>
<main class="wrap">
  <div class="top"><div><h1 style="margin:0">Sharky</h1><div class="sub">Conversaciones, atención humana, datos comerciales y métricas.</div></div><div><a href="/configuracion.php">← Configuración</a></div></div>
  <div id="msg" class="msg" role="status"></div>
  <section class="grid" id="cards"></section>

  <section class="panel">
    <div class="brain-head"><h2>Sharky 3.0 — Brain</h2><span id="brain-status" class="pill collecting">Acumulando evidencia</span></div>
    <p class="brain-note" id="brain-note">El Brain observa las decisiones reales y las compara con Sharky actual. El diagnóstico no guarda texto de conversaciones, teléfonos, nombres ni campañas.</p>
    <div class="brain-grid" id="brain-cards"></div>
    <p class="brain-note" id="brain-rule"></p>
    <div style="overflow:auto"><table class="metrics"><thead><tr><th>Decisión live</th><th>Brain proponía</th><th>Casos</th><th>Riesgo</th></tr></thead><tbody id="brain-mismatches"></tbody></table></div>
    <div class="brain-live" id="brain-live-wrap">
      <h3>Brain Live 2B-A</h3>
      <p class="brain-note">Tráfico real del canary. Estas cifras no amplían autoridad automáticamente; sirven para decidir si el mismo router restringido puede aumentar cobertura.</p>
      <div class="brain-grid" id="brain-live-cards"></div>
      <div class="brain-gate" id="brain-live-gate"></div>
    </div>
  </section>

  <section class="panel"><h2>Conversaciones en atención humana</h2><div id="takeovers"></div></section>
  <section class="panel"><h2>Fuente de verdad comercial</h2><p class="sub">Estos valores alimentan a Sharky en web y WhatsApp. Los horarios y cursos vigentes se leen directamente del backend.</p><div id="config"></div></section>
  <section class="panel"><h2>Últimos 7 días</h2><div style="overflow:auto"><table class="metrics"><thead><tr><th>Fecha</th><th>Texto</th><th>Audios</th><th>Respuestas WA</th><th>Respuestas web</th><th>Takeovers</th><th>Llamadas IA</th></tr></thead><tbody id="metrics"></tbody></table></div></section>
</main>
<script>
const M=document.getElementById('msg'),T=document.getElementById('takeovers'),C=document.getElementById('config'),K=document.getElementById('cards'),R=document.getElementById('metrics'),BS=document.getElementById('brain-status'),BN=document.getElementById('brain-note'),BC=document.getElementById('brain-cards'),BM=document.getElementById('brain-mismatches'),BR=document.getElementById('brain-rule'),BLC=document.getElementById('brain-live-cards'),BLG=document.getElementById('brain-live-gate');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reason={manual:'Toma manual',requested_human:'Pidió humano',frustration:'Frustración',unresolved:'Sin resolver',manual_legacy:'Toma manual'};
async function api(body){const r=await fetch('/api/sharky-admin.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}
function n(v){return Number(v||0).toLocaleString('es-MX')}
function pct(v){return `${Number(v||0).toLocaleString('es-MX',{minimumFractionDigits:1,maximumFractionDigits:1})}%`}
function cards(t){K.innerHTML=`<div class="card"><strong>${n(t.inbound_text)}</strong><span>mensajes de texto / 7 días</span></div><div class="card"><strong>${n(t.inbound_audio)}</strong><span>notas de voz / 7 días</span></div><div class="card"><strong>${n(t.takeovers)}</strong><span>pases a humano / 7 días</span></div><div class="card"><strong>${n(t.openai_calls)}</strong><span>llamadas de respuesta IA / 7 días</span></div>`}
function brain(b){b=b||{};const review=String(b.status||'').startsWith('review_');BS.className=`pill ${b.status==='candidate'?'candidate':review?'review':'collecting'}`;BS.textContent=b.routing_live?`Fase 2B-A · ${n(b.canary_pct)}% canary`:(b.status_label||'Acumulando evidencia');BN.innerHTML=b.routing_live?`El shadow sigue comparando la decisión original con Brain, pero <strong>Fase 2B-A puede corregir únicamente rutas guiadas de bajo riesgo</strong> dentro del canary. Conversación abierta, alumnos, profesores, pagos, formularios, takeover, flows activos y decisiones deterministas siguen fuera de su autoridad.`:`El Brain observa las decisiones reales y las compara con Sharky actual. <strong>No controla todavía el routing ni los mensajes.</strong> El diagnóstico no guarda texto de conversaciones, teléfonos, nombres ni campañas.`;BC.innerHTML=`<div class="brain-card"><strong>${n(b.observed)}</strong><span>decisiones observadas desde diagnóstico</span></div><div class="brain-card"><strong>${pct(b.agreement_pct)}</strong><span>coincidencia live ↔ Brain</span></div><div class="brain-card"><strong>${n(b.mismatches)}</strong><span>divergencias clasificadas</span></div><div class="brain-card"><strong>${n(b.errors)}</strong><span>errores del observer</span></div>`;BR.textContent=`Puerta de seguridad: mínimo ${n(b.minimum_observations)} observaciones, ${pct(b.minimum_agreement_pct)} de consistencia, 0 errores y 0 divergencias en rutas protegidas. Faltan ${n(b.remaining_observations)} observaciones para el mínimo.${b.routing_live?' 2B-A mantiene answer_user y continue_discovery en shadow.':''}`;const rows=Array.isArray(b.pairs)?b.pairs:[];BM.innerHTML=rows.length?rows.map(x=>`<tr><td>${esc(x.live_label)}</td><td>${esc(x.brain_label)}</td><td>${n(x.count)}</td><td class="${x.blocking?'danger-text':''}">${x.blocking?'Protegida':'Bajo riesgo'}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Aún no hay divergencias clasificadas.</td></tr>'}
function brainLive(b,t){b=b||{};t=t||{};const eligible=Number(t.brain_live_2ba_eligible||0),applied=Number(t.brain_live_2ba_applied||0),aligned=Number(t.brain_live_2ba_aligned||0),blocked=Number(t.brain_live_2ba_blocked||0),openBlocked=Number(t.brain_live_2ba_open_conversation_blocked||0),guided=Number(t.brain_live_2ba_applied_start_guided_qualification||0),menu=Number(t.brain_live_2ba_applied_show_commercial_menu||0),target=20,remaining=Math.max(0,target-applied);BLC.innerHTML=`<div class="brain-card"><strong>${n(b.canary_pct)}</strong><span>% del canary configurado</span></div><div class="brain-card"><strong>${n(eligible)}</strong><span>casos elegibles evaluados</span></div><div class="brain-card"><strong>${n(applied)}</strong><span>intervenciones live aplicadas</span></div><div class="brain-card"><strong>${n(blocked)}</strong><span>bloqueos por safety gate</span></div><div class="brain-card"><strong>${n(aligned)}</strong><span>casos donde live ya coincidía</span></div><div class="brain-card"><strong>${n(openBlocked)}</strong><span>intentos conversacionales bloqueados</span></div><div class="brain-card"><strong>${n(guided)}</strong><span>calificaciones guiadas iniciadas</span></div><div class="brain-card"><strong>${n(menu)}</strong><span>menús comerciales guiados</span></div>`;BLG.innerHTML=b.routing_live?`Puerta operativa conservadora: mantener el canary actual hasta acumular <strong>${target} intervenciones live reales</strong> sin regresiones del funnel ni incidentes en rutas protegidas. Llevamos <strong>${n(applied)}</strong>; faltan <strong>${n(remaining)}</strong>. Llegar al número no sube el porcentaje automáticamente: requiere revisión de la evidencia.`:'2B-A está deshabilitado. El shadow puede seguir acumulando evidencia, pero Brain no está aplicando routing live.'}
function takeoverRows(rows){if(!rows.length){T.innerHTML='<div class="empty">No hay conversaciones pausadas para Sharky.</div>';return}T.innerHTML=rows.map(x=>`<div class="takeover"><div><strong>•••• ${esc(x.phone_last4||'----')}</strong><br><span class="pill">${esc(reason[x.reason]||x.reason||'Humano')}</span></div><div><small>${esc(x.activated_at?new Date(x.activated_at).toLocaleString('es-MX'):'Sin fecha')}</small></div><div class="summary">${esc(x.summary||'Sin resumen disponible.')}</div><div><button class="btn primary" data-resume="${esc(x.contact_hash)}">Reactivar Sharky</button></div></div>`).join('');T.querySelectorAll('[data-resume]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Devolver esta conversación a Sharky?'))return;try{await api({accion:'RESUME',contact_hash:b.dataset.resume});M.textContent='Sharky reactivado para esa conversación.';await load()}catch(e){M.textContent=e.message}})}
function configRows(rows){C.innerHTML=rows.map(x=>{const label=x.etiqueta||x.clave.replace(/^sharky_/,'').replaceAll('_',' ');const control=x.tipo==='checkbox'?`<label class="toggle"><input type="checkbox" data-key="${esc(x.clave)}" ${String(x.valor)==='1'?'checked':''}><span>${String(x.valor)==='1'?'Habilitado':'Deshabilitado'}</span></label>`:`<input data-key="${esc(x.clave)}" value="${esc(x.valor)}">`;return `<div class="config-row"><div class="label"><strong>${esc(label)}</strong><small>${esc(x.descripcion)}</small></div>${control}<button class="btn primary">Guardar</button></div>`}).join('');C.querySelectorAll('input[type=checkbox]').forEach(i=>i.onchange=()=>{const s=i.parentElement.querySelector('span');if(s)s.textContent=i.checked?'Habilitado':'Deshabilitado'});C.querySelectorAll('button').forEach(b=>b.onclick=async()=>{const i=b.parentElement.querySelector('input');const valor=i.type==='checkbox'?(i.checked?'1':'0'):i.value;try{await api({accion:'CONFIG',clave:i.dataset.key,valor});M.textContent='Dato actualizado. Sharky usará el nuevo valor desde el siguiente mensaje.';await load()}catch(e){M.textContent=e.message}})}
function metricRows(rows){R.innerHTML=rows.map(x=>{const c=x.counters||{};return `<tr><td>${esc(x.date)}</td><td>${n(c.inbound_text)}</td><td>${n(c.inbound_audio)}</td><td>${n(c.answers_whatsapp)}</td><td>${n(c.answers_web)}</td><td>${n(c.takeovers)}</td><td>${n(c.openai_calls)}</td></tr>`}).join('')}
async function load(){try{const r=await fetch('/api/sharky-admin.php',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar Sharky');cards(d.totals||{});brain(d.brain_shadow||{});brainLive(d.brain_shadow||{},d.totals||{});takeoverRows(d.takeovers||[]);configRows(d.configuracion||[]);metricRows(d.metrics||[])}catch(e){M.textContent=e.message||'No se pudo cargar Sharky'}}
load();
</script>
</body>
</html>